```C
#include <iostream>
#define MaxSize 50
using namespace std;

typedef struct {
    int data[MaxSize];
    int front, rear;
}SqQueue;
```

初始化

```C
void init(SqQueue& Q) {
    Q.rear = Q.front = 0;
}
```

判空

```C
bool isEmpty(SqQueue q) {
    if (q.front==q.rear) {
        return true;
    }
    return false;
}
```

入队

```C
bool EnQueue(SqQueue &Q,int data) {
    //队满
    if ((Q.rear+1)%MaxSize==Q.front) {
        return false;
    }
    Q.data[Q.rear] = data;
    //1%50 = 1、2%50=2、3%50=3....50%50=0，用这种方式就可以构造一个完整递进闭环
    Q.rear = (Q.rear + 1) %MaxSize;
    return true;
}
```

出队

```C
bool DeQueue(SqQueue &Q) {
    if (Q.rear==Q.front) {
        return false;
    }
    int x = Q.data[Q.front];
    cout << "出队：" << x << endl;
    //头指针后移
    Q.front = (Q.front + 1) % MaxSize;
    return true;

}
```

