    S.top = -1;//初始化栈顶指针
}
```

判空

```c
bool StatckEmpty(SqStack S) {
    if (S.top == -1)
        return true;
    else
        return false;
}
```

进栈

```c
bool push(SqStack& S, int data) {
    if (S.top == MaxSize - 1)
        return false;
    cout << "指针：" << S.top << endl;
    S.data[++S.top] = data;
    cout << "压栈成功：" << S.top << endl;
    return true;
}
```

出栈

```c
bool pop(SqStack &S,int &x) {
    if (S.top == -1)
        return false;
    x = S.data[S.top--];
    return true;
}
```

